import { formatQuizCodeQuestion, QuizQuestion } from '../../utils/quizQuestions';
import { WORLD_12_QUIZ_SETS } from './quizSets';
const W = 'world-12';
type Diff = 'easy' | 'medium' | 'hard';
const xp = { easy: 10, medium: 15, hard: 20 } as const;
const code = (src: string[]) => {
  if (src.some((l) => /^\s*fun main\s*\(/.test(l))) return src;
  const decl = /^(?:import\b|(?:(?:abstract|open|sealed|data|enum)\s+)*(?:class|interface|object)\b|(?:inline\s+)?fun\s+(?!main\b)|typealias\b|___\s+Names\b)/;
  const top: string[] = [];
  let depth = 0, split = 0;
  for (; split < src.length; split++) {
    if (depth === 0 && !decl.test(src[split].trim())) break;
    top.push(src[split]);
    for (const ch of src[split]) { if (ch === '{') depth++; else if (ch === '}') depth--; }
  }
  const statements = src.slice(split);
  if (!top.length) return ['fun main() {', ...src.map((l) => '  ' + l), '}'];
  return statements.length ? [...top, 'fun main() {', ...statements.map((l) => '  ' + l), '}'] : top;
};
const base = (id: string, lessonId: string, topic: string, concept: string, difficulty: Diff, question: string, explanation: string, hint: string) => ({ id, worldId: W, lessonId, topic, concept, difficulty, xp: xp[difficulty], question, explanation, hint });
const choice = (id: string,l: string,t: string,c: string,d: Diff,q: string,e: string,h: string,ok: string,bad: string[],extra: Record<string,unknown>={}) => ({...base(id,l,t,c,d,q,e,h),type:'single_choice' as const,options:[ok,...bad],answer:0,...extra});
const args = (tail: unknown[], concept: string, kind: 'predict' | 'multi' | 'fill' | 'error' | 'compare') => {
  if (typeof tail[0] === 'string') return { hint: tail[0], rest: tail.slice(1) };
  const focus = concept.toLowerCase();
  const hint = {
    predict: `Work out the ${focus} before following the printed value.`,
    multi: `Test each option against ${focus}.`,
    fill: `Use the syntax for ${focus}.`,
    error: `Find the line that breaks ${focus}.`,
    compare: `Compare how each version handles ${focus}.`,
  }[kind];
  return { hint, rest: tail };
};
const predict = (id: string,l: string,t: string,c: string,d: Diff,q: string,e: string,...tail: unknown[]) => { const {hint,rest}=args(tail,c,'predict'); const [src,out,bad]=rest as [string[],string,string[]]; return {...base(id,l,t,c,d,q,e,hint),type:'predict_output' as const,code:code(src),options:[out,...bad],monoOptions:true,answer:0}; };
const multi = (id: string,l: string,t: string,c: string,d: Diff,q: string,e: string,...tail: unknown[]) => { const {hint,rest}=args(tail,c,'multi'); const [src,opts,answers]=rest as [string[],string[],number[]]; return {...base(id,l,t,c,d,q,e,hint),type:'multi_select' as const,code:code(src),options:opts,monoOptions:opts.every(x=>/^(?:[a-z]\w*\(|[A-Z]\w*<[^>]+>\s*=)/.test(x)),answers}; };
const fill = (id: string,l: string,t: string,c: string,q: string,e: string,...tail: unknown[]) => { const {hint,rest}=args(tail,c,'fill'); const [src,chips,answer]=rest as [string[],string[],string]; return {...base(id,l,t,c,'medium',q,e,hint),type:'fill_blank' as const,code:code(src),chips,answer}; };
const findError = (id: string,l: string,t: string,c: string,d: Diff,q: string,e: string,...tail: unknown[]) => { const {hint,rest}=args(tail,c,'error'); const [src,errorLine,note]=rest as [string[],number,string]; const lines=code(src); const target=src[errorLine]?.trim(); const keyed=lines.findIndex(x=>x.trim()===target); return {...base(id,l,t,c,d,q,e,hint),type:'find_error' as const,code:lines,errorLine:keyed>=0?keyed:errorLine,errorNote:note}; };
const compare = (id: string,l: string,t: string,c: string,d: Diff,q: string,e: string,...tail: unknown[]) => { const {hint,rest}=args(tail,c,'compare'); const [a,b,answer]=rest as [string[],string[],0|1]; return {...base(id,l,t,c,d,q,e,hint),type:'code_comparison' as const,a:code(a),b:code(b),answer}; };
const setQ = (n: number,setId: string,c: string,d: Diff,type: QuizQuestion['type'],q: string,e: string,h: string,data: Record<string,unknown>) => { const s=WORLD_12_QUIZ_SETS.find(x=>x.id===setId)!; return {...base('w12q-set-'+n,s.lessonIds.at(-1)!,s.title,c,d,q,e,h),setId,type,...data} as QuizQuestion; };
const bossQ = (n: number,c: string,d: Diff,type: QuizQuestion['type'],q: string,e: string,h: string,data: Record<string,unknown>) => ({...base('w12q-boss-'+n,'world-12-boss','Generic Data Toolkit',c,d,q,e,h),type,...data} as QuizQuestion);

